Implementation of the check which probably could work:

```js
if (__DEV__) {
  // defined in index widget
  function isIndexWidget(widget: Widget): widget is Index {
    return widget.$$type === 'ais.index';
  }

  // pretty much the same as resolveScopedResultsFromWidgets
  function getIndexIds(widgets: Widget[]): string[] {
    const indexWidgets = widgets.filter(isIndexWidget);
  
    return indexWidgets.reduce<string[]>((scopedResults, current) => {
      return scopedResults.concat(
        current.getIndexId(),
        ...getIndexIds(current.getWidgets())
      );
    }, []);
  }

  const indexIds = Object.keys(initialUiState);
  const expectedIndexIds = getIndexIds(mainIndex.getWidgets());

  if (indexIds.every(id => expectedIndexIds.indexOf(id) === -1)) {
    console.log('warning')
  }
}
```
